typedef struct {
    int x, y;
    int idx;
} Pair;

Pair heap[MAXN];
int hsize;

void swap(Pair *a, Pair *b) {
    Pair t = *a;
    *a = *b;
    *b = t;
}

void push(int x, int y) {
    heap[hsize].x = x;
    heap[hsize].y = y;
    heap[hsize].idx = pos[x];
    int i = hsize++;
    while (i > 0) {
        int par = (i - 1) / 2;
        if (heap[par].x < heap[i].x || (heap[par].x == heap[i].x && heap[par].y < heap[i].y))
            break;
        swap(&heap[par], &heap[i]);
        i = par;
    }
}

Pair pop() {
    Pair res = heap[0];
    heap[0] = heap[--hsize];
    int i = 0;
    while (1) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        int smallest = i;
        if (left < hsize && (heap[left].x < heap[smallest].x || 
            (heap[left].x == heap[smallest].x && heap[left].y < heap[smallest].y)))
            smallest = left;
        if (right < hsize && (heap[right].x < heap[smallest].x || 
            (heap[right].x == heap[smallest].x && heap[right].y < heap[smallest].y)))
            smallest = right;
        if (smallest == i) break;
        swap(&heap[i], &heap[smallest]);
        i = smallest;
    }
    return res;
}

