#define INF 1000000007

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *p = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &p[i]);

    /* dp[l][r]: lexicographically smallest sequence obtainable from subarray p[l..r]
       represented by:
       - first value of the sequence
       - which pair (k,k+1) is chosen last in this interval
       Since q is built by repeatedly putting chosen pairs to the front,
       the final sequence for interval [l..r] is:
         best(left part), best(right part), p[k], p[k+1]
       where removing pair (k,k+1) splits interval into left/right parts.

       We compare candidates lazily using ranks of smaller intervals.
    */

    int size = N + 2;

    int **bestk = (int**)malloc(size * sizeof(int*));
    int **rankv = (int**)malloc(size * sizeof(int*));
    for (int i = 0; i < size; i++) {
        bestk[i] = (int*)malloc(size * sizeof(int));
        rankv[i] = (int*)malloc(size * sizeof(int));
        for (int j = 0; j < size; j++) {
            bestk[i][j] = -1;
            rankv[i][j] = 0;
        }
    }

    /* Empty intervals */
    for (int l = 1; l <= N + 1; l++) rankv[l][l - 1] = 1;

    /* Helper arrays for ranking intervals of same length */
    typedef struct {
        int a1, a2, a3, a4;
        int l, r;
    } Node;

    Node *arr = (Node*)malloc((N + 1) * sizeof(Node));

    for (int len = 2; len <= N; len += 2) {
        int cnt = 0;
        for (int l = 1; l + len - 1 <= N; l++) {
            int r = l + len - 1;

            int bk = -1;

            for (int k = l; k < r; k++) {
                int leftLen = k - l;
                int rightLen = r - (k + 1);
                if ((leftLen & 1) || (rightLen & 1)) continue;

                /* Candidate sequence:
                   seq(l,k-1) + seq(k+2,r) + p[k], p[k+1]
                 */

                if (bk == -1) {
                    bk = k;
                    continue;
                }

                /* Compare candidate k vs current bk lexicographically */
                int l1 = l, r1 = bk - 1, l2 = bk + 2, r2 = r;
                int c1 = l, d1 = k - 1, c2 = k + 2, d2 = r;

                /* We compare concatenations:
                   A = S(l1,r1) + S(l2,r2) + [p[bk], p[bk+1]]
                   B = S(c1,d1) + S(c2,d2) + [p[k], p[k+1]]
                 */

                int better = 0, decided = 0;

                int lenA1 = (l1 <= r1) ? (r1 - l1 + 1) : 0;
                int lenB1 = (c1 <= d1) ? (d1 - c1 + 1) : 0;

                if (lenA1 == 0 && lenB1 == 0) {
                    /* compare second parts */
                } else if (lenA1 == 0) {
                    better = 1; /* compare p from A with first of B? not enough */
                } else if (lenB1 == 0) {
                    better = 0;
                }

                /* General lexicographic compare using recursive ranks and first elements */
                /* Since all subintervals have unique ranks for full sequences of same length,
                   compare concatenations by parts. */

                int partsA[3][2] = {{l1, r1}, {l2, r2}, {bk, bk + 1}};
                int partsB[3][2] = {{c1, d1}, {c2, d2}, {k, k + 1}};

                int ia = 0, ib = 0;
                while (ia < 3 && ib < 3) {
                    while (ia < 3 && partsA[ia][0] > partsA[ia][1]) ia++;
                    while (ib < 3 && partsB[ib][0] > partsB[ib][1]) ib++;
                    if (ia == 3 || ib == 3) break;

                    int la = partsA[ia][0], ra = partsA[ia][1];
                    int lb = partsB[ib][0], rb = partsB[ib][1];
                    int lena = ra - la + 1;
                    int lenb = rb - lb + 1;

                    if (lena == 2 && (la == bk && ra == bk + 1) &&
                        lenb == 2 && (lb == k && rb == k + 1)) {
                        if (p[bk] != p[k]) {
                            better = (p[k] < p[bk]);
                            decided = 1;
                            break;
                        }
                        if (p[bk + 1] != p[k + 1]) {
                            better = (p[k + 1] < p[bk + 1]);
                            decided = 1;
                            break;
                        }
                        ia++; ib++;
                        continue;
                    }

                    if (lena == 2 && (la == bk && ra == bk + 1)) {
                        int firstb;
                        if (lb == k && rb == k + 1) firstb = p[k];
                        else {
                            int kb = bestk[lb][rb];
                            int ll = lb, rr = kb - 1;
                            if (ll <= rr) {
                                int kk = bestk[ll][rr];
                                /* first element of interval [lb..rb] */
                                int L = lb, R = rb;
                                int curk = bestk[L][R];
                                int a = L, b = curk - 1, c = curk + 2, d = R;
                                if (a <= b) {
                                    while (1) {
                                        int kk2 = bestk[a][b];
                                        int aa = a, bb = kk2 - 1;
                                        int cc = kk2 + 2, dd = b;
                                        if (aa <= bb) { a = aa; b = bb; continue; }
                                        if (cc <= dd) { a = cc; b = dd; continue; }
                                        firstb = p[kk2];
                                        break;
                                    }
                                } else if (c <= d) {
                                    int x = c, y = d;
                                    while (1) {
                                        int kk2 = bestk[x][y];
                                        int aa = x, bb = kk2 - 1;
                                        int cc = kk2 + 2, dd = y;
                                        if (aa <= bb) { x = aa; y = bb; continue; }
                                        if (cc <= dd) { x = cc; y = dd; continue; }
                                        firstb = p[kk2];
                                        break;
                                    }
                                } else firstb = p[curk];
                            }
                        }
                        if (p[bk] != firstb) {
                            better = (firstb < p[bk]);
                            decided = 1;
                            break;
                        }
                        /* if equal, fallback to ranks by lengths only when same length */
                    }

                    if (lenb == 2 && (lb == k && rb == k + 1)) {
                        int firsta;
                        if (la == bk && ra == bk + 1) firsta = p[bk];
                        else {
                            int L = la, R = ra;
                            int curk = bestk[L][R];
                            int a = L, b = curk - 1, c = curk + 2, d = R;
                            if (a <= b) {
                                while (1) {
                                    int kk2 = bestk[a][b];
                                    int aa = a, bb = kk2 - 1;
                                    int cc = kk2 + 2, dd = b;
                                    if (aa <= bb) { a = aa; b = bb; continue; }
                                    if (cc <= dd) { a = cc; y:
                                        ; }
                                    firsta = p[kk2];
                                    break;
                                }
                            } else if (c <= d) {
                                int x = c, y = d;
                                while (1) {
                                    int kk2 = bestk[x][y];
                                    int aa = x, bb = kk2 - 1;
                                    int cc = kk2 + 2, dd = y;
                                    if (aa <= bb) { x = aa; y = bb; continue; }
                                    if (cc <= dd) { x = cc; y = dd; continue; }
                                    firsta = p[kk2];
                                    break;
                                }
                            } else firsta = p[curk];
                        }
                        if (firsta != p[k]) {
                            better = (p[k] < firsta);
                            decided = 1;
                            break;
                        }
                    }

                    if (lena == lenb) {
                        int ra1 = (la == bk && ra == bk + 1) ? -1 : rankv[la][ra];
                        int rb1 = (lb == k && rb == k + 1) ? -1 : rankv[lb][rb];
                        if (ra1 != -1 && rb1 != -1) {
                            if (ra1 != rb1) {
                                better = (rb1 < ra1);
                                decided = 1;
                                break;
                            }
                            ia++; ib++;
                            continue;
                        }
                    }

                    /* Fallback by explicit expansion for small terminal cases */
                    int va[2], vb[2], ca = 0, cb = 0;
                    if (la == bk && ra == bk + 1) { va[ca++] = p[bk]; va[ca++] = p[bk + 1]; }
                    if (lb == k && rb == k + 1) { vb[cb++] = p[k]; vb[cb++] = p[k + 1]; }
                    if (ca && cb) {
                        if (va[0] != vb[0]) { better = (vb[0] < va[0]); decided = 1; break; }
                        if (va[1] != vb[1]) { better = (vb[1] < va[1]); decided = 1; break; }
                        ia++; ib++;
                        continue;
                    }

                    /* Should not reach here for valid structured comparison often.
                       Use ranks of whole concatenation approximation by first differing part length. */
                    int ra1 = (la <= ra && !(la == bk && ra == bk + 1)) ? rankv[la][ra] : INF;
                    int rb1 = (lb <= rb && !(lb == k && rb == k + 1)) ? rankv[lb][rb] : INF;
                    if (ra1 != rb1) {
                        better = (rb1 < ra1);
                        decided = 1;
                        break;
                    }
                    ia++; ib++;
                }

                if (!decided) {
                    if (p[k] < p[bk]) better = 1;
                    else if (p[k] > p[bk]) better = 0;
                    else if (p[k + 1] < p[bk + 1]) better = 1;
                    else better = 0;
                }

                if (better) bk = k;
            }

            bestk[l][r] = bk;
        }

        /* Assign ranks for this length by actual generated sequences */
        int cnt2 = 0;
        for (int l = 1; l + len - 1 <= N; l++) {
            int r = l + len - 1;
            int k = bestk[l][r];

            int leftRank = (l <= k - 1) ? rankv[l][k - 1] : 0;
            int rightRank = (k + 2 <= r) ? rankv[k + 2][r] : 0;

            arr[cnt2].a1 = leftRank;
            arr[cnt2].a2 = rightRank;
            arr[cnt2].a3 = p[k];
            arr[cnt2].a4 = p[k + 1];
            arr[cnt2].l = l;
            arr[cnt2].r = r;
            cnt2++;
        }

        int cmp_node(const void *A, const void *B) {
            const Node *x = (const Node*)A;
            const Node *y = (const Node*)B;
            if (x->a1 != y->a1) return x->a1 - y->a1;
            if (x->a2 != y->a2) return x->a2 - y->a2;
            if (x->a3 != y->a3) return x->a3 - y->a3;
            return x->a4 - y->a4;
        }

        qsort(arr, cnt2, sizeof(Node), cmp_node);

        int rk = 1;
        for (int i = 0; i < cnt2; i++) {
            if (i > 0 &&
                (arr[i].a1 != arr[i - 1].a1 ||
                 arr[i].a2 != arr[i - 1].a2 ||
                 arr[i].a3 != arr[i - 1].a3 ||
                 arr[i].a4 != arr[i - 1].a4)) rk++;
            rankv[arr[i].l][arr[i].r] = rk;
        }
    }

    /* Reconstruct answer from interval [1..N] */
    int *ans = (int*)malloc(N * sizeof(int));
    int top = 0;

    typedef struct { int l, r; } Seg;
    Seg *stack = (Seg*)malloc((N + 5) * sizeof(Seg));
    int sp = 0;
    stack[sp++] = (Seg){1, N};

    while (sp) {
        Seg cur = stack[--sp];
        if (cur.l > cur.r) continue;
        int k = bestk[cur.l][cur.r];
        /* sequence = left + right + pair */
        stack[sp++] = (Seg){k, k + 1};
        stack[sp++] = (Seg){k + 2, cur.r};
        stack[sp++] = (Seg){cur.l, k - 1};
    }

    for (int i = 0; i < sp; i++) {}

    /* The above stack contains pair intervals too; produce by DFS manually */
    sp = 0;
    stack[sp++] = (Seg){1, N};
    while (sp) {
        Seg cur = stack[--sp];
        if (cur.l > cur.r) continue;
        if (cur.r == cur.l + 1 && bestk[cur.l][cur.r] == cur.l) {
            ans[top++] = p[cur.l];
            ans[top++] = p[cur.r];
            continue;
        }
        int k = bestk[cur.l][cur.r];
        stack[sp++] = (Seg){k, k + 1};
        stack[sp++] = (Seg){k + 2, cur.r};
        stack[sp++] = (Seg){cur.l, k - 1};
    }

    for (int i = 0; i < N; i++) {
        if (i) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    return 0;
}

