int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> p(N + 1);
    for (int i = 1; i <= N; i++) cin >> p[i];

    // Let the chosen adjacent pairs (in the order they are removed from p) be:
    // (l1,l1+1), (l2,l2+1), ..., (lk,lk+1)
    // Then q is these pairs written in reverse removal order.
    //
    // Equivalently, if we decide the first pair of q, it must be some adjacent pair
    // in the current sequence, and after removing it, the remaining q suffix is solved
    // independently on the left and right parts.
    //
    // Define dp[l][r] (length even) as the lexicographically smallest sequence obtainable
    // from subarray p[l..r].
    //
    // The first pair in dp[l][r] must be some adjacent pair (i,i+1) inside [l,r].
    // Since it appears at the front of q, to minimize lexicographically:
    //   1) minimize p[i]
    //   2) if tied, minimize p[i+1]
    // After fixing that pair, the remainder is dp[l][i-1] followed by dp[i+2][r].
    //
    // We only need to know, for each interval, which adjacent pair is chosen first.
    // Then reconstruct recursively.

    vector<vector<int>> first(N + 2, vector<int>(N + 2, -1));

    for (int len = 2; len <= N; len += 2) {
        for (int l = 1; l + len - 1 <= N; l++) {
            int r = l + len - 1;
            int best = l;
            for (int i = l; i < r; i++) {
                if ((i - l) % 2 != 0) continue; // left part length must be even
                if (p[i] < p[best] || (p[i] == p[best] && p[i + 1] < p[best + 1])) {
                    best = i;
                }
            }
            first[l][r] = best;
        }
    }

    vector<int> ans;
    function<void(int,int)> build = [&](int l, int r) {
        if (l > r) return;
        int i = first[l][r];
        ans.push_back(p[i]);
        ans.push_back(p[i + 1]);
        build(l, i - 1);
        build(i + 2, r);
    };

    build(1, N);

    for (int i = 0; i < N; i++) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}

