int p[2001];
int N;
map<pair<int,int>,vector<int>> memo;
vector<int> solve(int l, int r){
    if(l>r) return {};
    auto key=make_pair(l,r);
    if(memo.count(key)) return memo[key];
    vector<int> best;
    for(int k=l+1;k<=r;k+=2){
        vector<int> cand={p[l],p[k]};
        // merge solve(l+1,k-1) and solve(k+1,r) optimally
        auto A=solve(l+1,k-1), B=solve(k+1,r);
        // merge A and B lex smallest - but they are fixed sequences, just concatenate in lex order
        vector<int> merged;
        int i=0,j=0;
        while(i<A.size()&&j<B.size()){if(A[i]<B[j])merged.push_back(A[i++]);else merged.push_back(B[j++]);}
        while(i<A.size())merged.push_back(A[i++]);
        while(j<B.size())merged.push_back(B[j++]);
        cand.insert(cand.end(),merged.begin(),merged.end());
        if(best.empty()||cand<best) best=cand;
    }
    return memo[key]=best;
}
