        // We will process the pairs in increasing order of first element.

        // For removing elements and finding neighbors we can use linked list style arrays.
        int[] prev = new int[N];
        int[] next = new int[N];
        for (int i = 0; i < N; i++) {
            prev[i] = i - 1;
            next[i] = i + 1;
        }
        prev[0] = -1;
        next[N - 1] = -1;

        // Priority queue stores pairs (value at index i, index i)
        // We'll only consider i where i has a next element.
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            return a[1] - b[1];
        });

        boolean[] removed = new boolean[N];
        for (int i = 0; i < N - 1; i++) {
            pq.offer(new int[]{p[i], i});
        }

        List<Integer> result = new ArrayList<>();

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int idx = cur[1];

            if (removed[idx] || next[idx] == -1 || removed[next[idx]]) continue;

            int idx2 = next[idx];

            // Take this pair
            result.add(p[idx]);
            result.add(p[idx2]);
            removed[idx] = true;
            removed[idx2] = true;

            // Link neighbors
            int pr = prev[idx];
            int nx = next[idx2];
            if (pr != -1) next[pr] = nx;
            if (nx != -1) prev[nx] = pr;

            // If after removal we have a new adjacent pair (pr, nx), add it to pq
            if (pr != -1 && nx != -1 && !removed[pr] && !removed[nx]) {
                pq.offer(new int[]{p[pr], pr});
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int v : result) {
            sb.append(v).append(" ");
        }
        System.out.println(sb.toString().trim());
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        LinkedList<Integer> p = new LinkedList<>();
        for (int i = 0; i < N; i++) p.add(sc.nextInt());

        int[] q = new int[N];
        int qPos = 0; // fill q from front

        // We pick pairs to place at positions qPos, qPos+1, ...
        // Each time pick the lex smallest pair at odd index (0-indexed even index)

        while (!p.isEmpty()) {
            // Find best pair at even 0-indexed position
            int bestIdx = -1;
            int bestX = Integer.MAX_VALUE, bestY = Integer.MAX_VALUE;
            for (int i = 0; i < p.size() - 1; i += 2) {
                int x = p.get(i), y = p.get(i+1);
                if (x < bestX || (x == bestX && y < bestY)) {
                    bestX = x; bestY = y; bestIdx = i;
                }
            }
            q[qPos++] = bestX;
            q[qPos++] = bestY;
            p.remove(bestIdx);
            p.remove(bestIdx);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            if (i > 0) sb.append(' ');
            sb.append(q[i]);
        }
        System.out.println(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static int[] p;

    // segment tree for range minimum query on values, storing index of minimum
    static class SegTree {
        int n;
        int[] idx;
        int[] arr;
        boolean evenParity; // true: only indices with even local parity are active, false: odd local parity

        SegTree(int[] base, boolean evenParity) {
            this.arr = base;
            this.evenParity = evenParity;
            n = 1;
            while (n < base.length) n <<= 1;
            idx = new int[n << 1];
            Arrays.fill(idx, -1);
            for (int i = 0; i < base.length; i++) {
                if (((i & 1) == 0) == evenParity) idx[n + i] = i;
            }
            for (int i = n - 1; i >= 1; i--) idx[i] = better(idx[i << 1], idx[i << 1 | 1]);
        }

        int better(int a, int b) {
            if (a == -1) return b;
            if (b == -1) return a;
            return arr[a] < arr[b] ? a : b;
        }

        int query(int l, int r) { // [l, r)
            int leftRes = -1, rightRes = -1;
            for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
                if ((l & 1) == 1) leftRes = better(leftRes, idx[l++]);
                if ((r & 1) == 1) rightRes = better(idx[--r], rightRes);
            }
            return better(leftRes, rightRes);
        }
    }

    static SegTree segEven, segOdd;

    static class Node implements Comparable<Node> {
        int l, r;
        int firstIdx, secondIdx;
        int firstVal, secondVal;

        Node(int l, int r, int firstIdx, int secondIdx) {
            this.l = l;
            this.r = r;
            this.firstIdx = firstIdx;
            this.secondIdx = secondIdx;
            this.firstVal = p[firstIdx];
            this.secondVal = p[secondIdx];
        }

        @Override
        public int compareTo(Node o) {
            if (firstVal != o.firstVal) return Integer.compare(firstVal, o.firstVal);
            return Integer.compare(secondVal, o.secondVal);
        }
    }

    static Node buildNode(int l, int r) {
        if (l >= r) return null;
        // length is always even for valid intervals
        int firstIdx;
        if ((l & 1) == 0) firstIdx = segEven.query(l, r);
        else firstIdx = segOdd.query(l, r);

        int secondIdx;
        if (((firstIdx + 1) & 1) == 0) secondIdx = segEven.query(firstIdx + 1, r);
        else secondIdx = segOdd.query(firstIdx + 1, r);

        return new Node(l, r, firstIdx, secondIdx);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        p = new int[N];
        for (int i = 0; i < N; i++) p[i] = fs.nextInt();

        segEven = new SegTree(p, true);
        segOdd = new SegTree(p, false);

        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.add(buildNode(0, N));

        int[] ans = new int[N];
        int ptr = 0;

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            ans[ptr++] = cur.firstVal;
            ans[ptr++] = cur.secondVal;

            int l = cur.l, i = cur.firstIdx, j = cur.secondIdx, r = cur.r;

            if (l < i) pq.add(buildNode(l, i));
            if (i + 1 < j) pq.add(buildNode(i + 1, j));
            if (j + 1 < r) pq.add(buildNode(j + 1, r));
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans[i]);
        }
        System.out.println(sb);
    }
}
